def f(x: int, k: int) -> int:
    """Remove all factors of k from x"""
    while x % k == 0:
        x //= k
    return x

def solve_problem(n: int, k: int, a: List[int]) -> Tuple[bool, List[Tuple[int, int]]]:
    """
    Try to find a sequence of operations to reach 1.
    Returns (True, operations) if possible, (False, []) otherwise.
    """
    # Strategy: Use BFS to explore the space of possible states
    # State is represented by a tuple of the current numbers on the blackboard

    from collections import deque

    # Initial state: sorted tuple of numbers to have deterministic states
    initial_state = tuple(sorted(a))

    # visited states
    visited = {initial_state}

    # Queue stores (current_state, operations_history)
    queue = deque([(initial_state, [])])

    target = (1,)

    while queue:
        state, ops = queue.popleft()

        if state == target:
            return True, ops

        # Try all pairs to combine
        length = len(state)
        for i in range(length):
            for j in range(i + 1, length):
                x = state[i]
                y = state[j]
                z = f(x + y, k)

                # Create new state without x and y, with z
                new_state_list = list(state)
                new_state_list[i] = z
                new_state_list.pop(j-1)  # Adjust index after removal
                new_state = tuple(sorted(new_state_list))

                if new_state not in visited:
                    visited.add(new_state)
                    new_ops = ops + [(x, y)]
                    queue.append((new_state, new_ops))

    # Reconstruct path on success - but BFS already stores paths
    # If we exit without finding target, return No solution
    return False, []

