    lines = input_str.strip().split('\n')

    n, m, k, p = map(int, lines[0].split())

    bamboos = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        h, a = int(parts[0]), int(parts[1])
        bamboos.append((h, a))

    def simulate(days, strikes_per_day, contr):
        for h, a in bamboos:
            for _ in range(days):
                if strikes_per_day > 0:
                    if contr > 0:
                        h -= contr
                        strikes_per_day -= 1
                        if strikes_per_day < 0:
                            break
                    if h < 0:
                        h = 0
                h += a
        return h

    def check(max_val):
        for h, a in bamboos:
            # Each day: we can strike at most k times, each strike reduces by p
            # The bamboo grows by a each day
            # After m days
            for day in range(m):
                # Before growth, current height is h
                # We can reduce by at most k*p
                # After growth, h increases by a
                if h > max_val:
                    # Need to reduce it
                    needed = h - max_val
                    reduction = k * p
                    if reduction >= needed:
                        h -= needed
                    else:
                        h -= reduction
                        if h < 0:
                            h = 0
                h += a

        max_final = 0
        for h, a in bamboos:
            for day in range(m):
                for _ in range(k):
                    h = max(0, h - p)
                h += a
            if h > max_final:
                max_final = h
        return max_final <= max_val

    # Binary search for the answer
    left = 0
    right = 10**18
    ans = right

    while left <= right:
        mid = (left + right) // 2
        # Check if it's possible to have max height <= mid
        possible = True
        for h, a in bamboos:
            temp = h
            for day in range(m):
                for _ in range(k):
                    temp = max(0, temp - p)
                temp += a
            if temp > mid:
                possible = False
        if possible:
            ans = mid
            right = mid - 1
        else:
            left = mid + 1

    return str(ans)

