def solution_real(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())

    dwarves = []
    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        dwarves.append((x, y))

    subways = []
    for i in range(n + 1, n + 1 + k):
        if i < len(lines):
            x, y = map(int, lines[i].split())
            subways.append((x, y))

    # Binary search on answer
    def check(time):
        # Check if there's a point where all dwarves arrive in time
        # Guenin/median approach

        # For L1 distance, the optimal point is related to median of coordinates
        # But with subway, it's more complex

        # Try key candidate points
        candidates = set()
        for x, y in dwarves:
            candidates.add((x, y))
            # Allow some margin for subway
            for mx in range(-1, 2):
                for my in range(-1, 2):
                    candidates.add((x + mx, y + my))

        for sx, sy in subways:
            candidates.add((sx, sy))
            for mx in range(-2, 3):
                for my in range(-2, 3):
                    candidates.add((sx + mx, sy + my))

        # Cross coordinates
        if len(dwarves) >= 2:
            for i in range(min(10, len(dwarves))):
                for j in range(i, min(10, len(dwarves))):
                    cx, cy = (dwarves[i][0] + dwarves[j][0]) // 2, (dwarves[i][1] + dwarves[j][1]) // 2
                    candidates.add((cx, cy))
                    candidates.add((cx + 1, cy))
                    candidates.add((cx, cy + 1))
                    candidates.add((cx - 1, cy))
                    candidates.add((cx, cy - 1))

        for px, py in candidates:
            ok = True
            for dx, dy in dwarves:
                best = abs(dx - px) + abs(dy - py)
                if k > 0:
                    for sx, sy in subways:
                        best = min(best, abs(dx - sx) + abs(dy - sy) + abs(sx - px) + abs(sy - py))
                if best > time:
                    ok = False
                    break
            if ok:
                return True
        return False

    lo, hi = 0, 200000000  # Max possible answer
    ans = hi

    for _ in range(60):
        mid = (lo + hi) // 2
        if mid < 0:
            lo = 0
            continue
        if check(mid):
            ans = mid
            hi = mid
        else:
            lo = mid + 1

    return f"{ans}\n"

