def check_g(seq):
    n = len(seq)
    if n <= 1:
        return True
    if all(x == 0 for x in seq):
        return True

    # Check for geometric progression
    ratio = None
    i = 0
    while i < n and seq[i] == 0:
        i += 1
    if i < n and seq[i] == 0:
        return True

    # Find the first two non-zero elements to determine ratio
    start = i
    if start + 1 < n and seq[start + 1] == 0:
        return False

    ratio = float(seq[start + 1]) / seq[start] if seq[start] != 0 else 0.0

    for j in range(start + 1, n):
        if seq[j] == 0:
            if seq[j - 1] != 0:
                return False
        else:
            if seq[j - 1] != 0:
                if seq[j] != seq[j - 1] * ratio or ratio == 0:
                    # Check for floating point issues
                    if seq[j] == 0 and seq[j - 1] != 0:
                        return False
                    new_ratio = float(seq[j]) / seq[j - 1] if seq[j - 1] != 0 else 0.0
                    if seq[j - 1] != 0:
                        if not (abs(new_ratio - ratio) < 1e-9):
                            return False

    return True

