def parse_utils(s):
    import re
    return tuple(int(x) for x in re.findall(r'\d+', s))

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "0\n"

    header = lines[0].split()
    N, M, K = int(header[0]), int(header[1]), int(header[2])

    transformers = []
    for i in range(1, K + 1):
        parts = list(map(int, lines[i].split()))
        x, y, d, t, e = parts[0], parts[1], parts[2], parts[3], parts[4]
        transformers.append({'x': x, 'y': y, 'd': d, 't': t, 'e': e})

    # Precompute transformer costs at each position
    # cost[i][j][time] = energy if transformer present
    cell_costs = defaultdict(dict)

    for trans in transformers:
        sx, sy, d, st, energy = trans['x'], trans['y'], trans['d'], trans['t'], trans['e']

        # Which positions does it visit and at what times?
        # Pattern: (sx,sy) at t, (sx+d, sy-d) at t+1, (sx+d, sy) at t+2, (sx, sy+d) at t+3
        cycle = [(sx, sy), (sx+d, sy-d), (sx+d, sy), (sx, sy+d)]

        for pos_idx, (px, py) in enumerate(cycle):
            pos_time = st + pos_idx

            # Check if this position-time is within grid bounds and relevant range
            if 0 <= pos_time < N + M:
                cost_key = step_key = (px, py)
                if step_key not in cell_costs:
                    cell_costs[step_key] = []
                # Add transformer energy if needs to be killed
                cell_costs[step_key].append(energy)

    # Actually need to track per time and position
    # cost_map[(row, col)] = list of energies at that position when visited

    # More accurate: compute cost for each reachable (i,j) at time i+j
    full_cost_map = {}  # (i,j) -> energy at that position when we arrive

    for trans in transformers:
        sx, sy, d, st, energy = trans['x'], trans['y'], trans['d'], trans['t'], trans['e']
        cycle = [(sx, sy), (sx+d, sy-d), (sx+d, sy), (sx, sy+d)]

        for pos_idx, (px, py) in enumerate(cycle):
            pos_time = st + pos_idx

            if 0 <= px < N and 0 <= py < M and 0 <= pos_time < N + M:
                key = (px, py)
                if key not in full_cost_map:
                    full_cost_map[key] = []

                # Check if this position-time is reachable
                # We can reach (px, py) at time (px + py)
                # Only if pos_time == px + py
                if pos_time == px + py:
                    full_cost_map[key].append(energy)

    # Now compute minimum energy path using DP
    # dp[i][j] = min energy to reach (i,j) at time i+j
    dp = [[0] * M for _ in range(N)]

    for i in range(N):
        for j in range(M):
            if i == 0 and j == 0:
                dp[i][j] = 0
            else:
                # Cost at this position when time = i+j
                key = (i, j)
                cost = 0
                if key in full_cost_map:
                    cost = sum(full_cost_map[key])  # sum all transformers at this pos at this time

                # Come from top or left
                top = left = float('inf')
                if i > 0:
                    top = dp[i-1][j]
                if j > 0:
                    left = dp[i][j-1]

                dp[i][j] = min(top, left) + cost

    result = dp[N-1][M-1]
    return str(result) + "\n"

