def solution(inp):
    path = inp.split()

    def parse_grid(path, idx):
        n, m = int(path[idx]), int(path[idx + 1])
        idx += 2
        grid = []
        for _ in range(n):
            row = path[idx]
            idx += 1
            grid.append(row)
        return grid, idx

    def count_squares(grid, n, m):
        result = 0

        # Check axis-aligned squares
        def check_frame(r0, c0, size):
            return (
                all(grid[r][c] == '1' for r in range(r0, r0 + size) for c in [c0, c0 + size - 1]) and
                all(grid[r'][c'] == '1' for r' in [r0, r0 + size - 1] for c' in range(c0, c0 + size))
            )

        for r in range(n):
            for c in range(m):
                if grid[r][c] == '1':
                    # Try all possible sizes for axis-aligned squares
                    for size in range(2, min(n - r, m - c) + 1):
                        if check_frame(r, c, size):
                            # Check no foreign 1s on frame
                            frame_ok = True
                            for dr in [-1, 0, 1]:
                                for dc in [-1, 0, 1]:
                                    if dr == 0 and dc == 0:
                                        continue
                                    tr, tc = r + dr, c + dc
                                    if 0 <= tr < n and 0 <= tc < m:
                                        if grid[tr][tc] == '1':
                                            frame_ok = False
                                            break
                                if not frame_ok:
                                    break
                            if frame_ok:
                                # Check interior is not all 1s (must have at least some empty space)
                                has_interior_1 = False
                                if size > 1:
                                    for i in range(1, size - 1):
                                        for j in range(1, size - 1):
                                            if r + i < n and c + j < m and grid[r + i][c + j] == '1':
                                                has_interior_1 = True
                                                break
                                        if has_interior_1:
                                            break
                                # If interior exists and contains 1s, still valid as long as it's framed
                                if frame_ok:
                                    result += 1

        # Check diagonal (diamond) squares
        diag_valid = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == '1':
                    # Try diamond sizes (1 = single cell, 2 = diamond with 5 cells)
                    diag_valid += 1  # Count all valid diamonds

        return result

