        grid, idx = parse_grid(path, idx)
        n, m = len(grid), len(grid[0])

        count = 0

        # Axis-aligned squares
        for s in range(2, min(n, m) + 1):
            for r in range(n - s + 1):
                for c in range(m - s + 1):
                    top = grid[r][c:c + s]
                    bottom = grid[r + s - 1][c:c + s]
                    left = ''.join(grid[i][c] for i in range(r, r + s))
                    right = ''.join(grid[i][c + s - 1] for i in range(r, r + s))

                    if all(ch == '1' for ch in top) and all(ch == '1' for ch in bottom) and \
                       all(ch == '1' for ch in left) and all(ch == '1' for ch in right):
                        # Check no touching 1s
                        frame_ok = True
                        frame_cells = set()
                        for i in range(r, r + s):
                            for j in range(c, c + s):
                                if i == r or i == r + s - 1 or j == c or j == c + s - 1:
                                    frame_cells.add((i, j))

                        for fr, fc in frame_cells:
                            for dr in [-1, 0, 1]:
                                for dc in [-1, 0, 1]:
                                    if dr == 0 and dc == 0:
                                        continue
                                    nr, nc = fr + dr, fc + dc
                                    if 0 <= nr < n and 0 <= nc < m:
                                        if (nr, nc) not in frame_cells and grid[nr][nc] == '1':
                                            frame_ok = False
                                            break
                                if not frame_ok:
                                    break
                            if not frame_ok:
                                break

                        if frame_ok:
