                                            break
                                    if has_zero:
                                        break
                                if not has_zero:
                                    continue
                            else:
                                continue
                            count += 1

        # Diagonal squares (diamonds)
        for r in range(n):
            for c in range(m):
                if grid[r][c] == '1':
                    max_diag = min(r, c, n - 1 - r, m - 1 - c)
                    for d in range(2, max_diag + 1):  # d >= 2 means actual diamond of size d+1
                        # Top vertex
                        if r - d >= 0 and r + d < n and c - d >= 0 and c + d < m:
                            if (grid[r - d][c] == '1' and grid[r + d][c] == '1' and
                                grid[r][c - d] == '1' and grid[r][c + d] == '1'):
                                # Found potential centered diamond
                                cells = {(r - d, c), (r + d, c), (r, c - d), (r, c + d)}
                                frame_ok = True
                                for fr, fc in cells:
                                    for dr in [-1, 0, 1]:
                                        for dc in [-1, 0, 1]:
                                            if dr == 0 and dc == 0:
                                                continue
                                            nr, nc = fr + dr, fc + dc
                                            if 0 <= nr < n and 0 <= nc < m:
                                                if (nr, nc) not in cells and grid[nr][nc] == '1':
                                                    frame_ok = False
                                                    break
                                        if not frame_ok:
                                            break
                                    if not frame_ok:
                                        break
                                if frame_ok:
                                    # Check interior - for diamond, interior is inside all 4 lines
                                    count += 1

        results.append(str(count))

    return '\n'.join(results)
