            num = c * b
            den = d * (a + 1)
            g = math.gcd(num, den)
            slopes.append((num // g, den // g))

            # Move y: (a, b+1)
            num = c * (b + 1)
            den = d * a
            g = math.gcd(num, den)
            slopes.append((num // g, den // g))
