    there exists at least one edge with label sum 0, one with sum 1,
    and one with sum 2.

    Uses inclusion-exclusion principle to count valid assignments.
    """
    try:
        lines = s.strip().split('\n')
        if not lines:
            return "0\n"

        first_line = lines[0].split()
        n, m = int(first_line[0]), int(first_line[1])

        if m == 0:
            # No edges, impossible to have all three edge types
            return "0\n"

        # Build adjacency list
        adj = [[] for _ in range(n + 1)]
        for i in range(1, m + 1):
            line = lines[i].split()
            u, v = int(line[0]), int(line[1])
            adj[u].append(v)
            adj[v].append(u)

        # Find connected components and track isolated vertices
        visited = [False] * (n + 1)
        components = []

        for i in range(1, n + 1):
            if not visited[i]:
                comp = []
                stack = [i]
                visited[i] = True
                while stack:
                    u = stack.pop()
                    comp.append(u)
                    for v in adj[u]:
                        if not visited[v]:
                            visited[v] = True
                            stack.append(v)
                components.append(comp)

    except:
        return "0\n"

    # Number of non-empty components and isolated vertices
    non_empty_count = 0
    isolated_count = 0

    # Build subgraphs for each component for IS counting
    comp_subgraphs = []

    for comp in components:
        idx_map = {v: i for i, v in enumerate(comp)}
        sub_adj = [[] for _ in range(len(comp))]
        for u in comp:
            for v in adj[u]:
                sub_adj[idx_map[u]].append(idx_map[v])
        comp_subgraphs.append(sub_adj)

        # Check if component has edges
        has_edges = False
        for i in range(len(sub_adj)):
            if sub_adj[i]:
                has_edges = True
                break
        if not has_edges:
            isolated_count += 1
        else:
            non_empty_count += 1

    # Compute number of independent sets for each component
    def count_independent_sets(sub_adj):
        k = len(sub_adj)
        if k == 0:
            return 1

        memo = {}

        def count(mask):
            if mask == (1 << k) - 1:
                return 1
            if mask in memo:
                return memo[mask]

            result = 0
            # Try including each vertex only if it's not adjacent to already selected vertices
            for bit in range(k):
                if not (mask & (1 << bit)):
                    # Check if bit has any neighbor in mask
                    conflict = False
                    for neighbor in sub_adj[bit]:
                        if mask & (1 << neighbor):
                            conflict = True
                            break
                    if not conflict:
                        result += mask_count_rec(sub_adj, mask | (1 << bit))
            memo[mask] = result
            return result

        def mask_count_rec(sub_adj, mask):
            if mask == 0:
                return 1
            if mask in memo:
                return memo[mask]

            result = 0
            # Find first unselected vertex
            for bit in range(len(sub_adj)):
                if not (mask & (1 << bit)):
                    # Try excluding this vertex
                    result += mask_count_rec(sub_adj, mask)
                    # Try including this vertex
                    conflict = False
                    for neighbor in sub_adj[bit]:
                        if mask & (1 << neighbor):
                            conflict = True
                            break
                    if not conflict:
                        result += mask_count_rec(sub_adj, mask | (1 << bit))
                    break

            memo[mask] = result
            return result

        return mask_count_rec(sub_adj, 0)

    # Compute number of bipartite components
    def is_bipartite(sub_adj):
        n_sub = len(sub_adj)
        if n_sub == 0 or n_sub == 1:
            return True

        colors = [-1] * n_sub

        def dfs(u):
            for v in sub_adj[u]:
                if colors[v] == -1:
                    colors[v] = 1 - colors[u]
                    if not dfs(v):
                        return False
                elif colors[v] == colors[u]:
                    return False
            return True

        for i in range(n_sub):
            if colors[i] == -1:
                colors[i] = 0
                if not dfs(i):
                    return False
        return True

    # P0: independent set of 0-vertices
    # P2: independent set of 1-vertices
    # P1: each component is monochromatic

    p0 = 1
    for sub_adj in comp_subgraphs:
        if sub_adj:
            p0 *= count_independent_sets(sub_adj)

    p2 = p0  # By symmetry

    p1 = 1 << len(components)

    # |P0 ∩ P1|: no (0,0) and no (0,1) edges
    # Non-edge components: all 1 (1 way), else free if no edges, or constrained for edges
    # Actually simplified: each non-trivial component must be all 1 (1 way each),
    # each trivial (isolated) component: 2 ways, each non-trivial component: 1 way
    p0_int_p1 = (1 << isolated_count) if non_empty_count > 0 else (1 << len(components))

    if non_empty_count == 0:
        p0_int_p1 = 1 << len(components)
    else:
        p0_int_p1 = 1 << isolated_count

    p1_int_p2 = p0_int_p1

    # |P0 ∩ P2|: no (0,0) and no (1,1) edges = all edges sum 1
    # Must be 2-colorable, 2 ways per bipartite component
    all_bipartite = True
    bipartite_ways = 1

    for sub_adj in comp_subgraphs:
        if len(sub_adj) == 0:
            continue
        if sub_adj and not is_bipartite(sub_adj):
            all_bipartite = False
            break
        bipartite_ways *= 2

    if all_bipartite:
        p0_int_p2 = bipartite_ways
    else:
        p0_int_p2 = 0

    # |P0 ∩ P1 ∩ P2|: impossible for m > 0
    if m == 0:
        p0_int_p1_int_p2 = 1
    else:
        p0_int_p1_int_p2 = 0

    # Inclusion-exclusion
    union = p0 + p1 + p2 - p0_int_p1 - p0_int_p2 - p1_int_p2 + p0_int_p1_int_p2

    total = 1 << n
    result = total - union

    return f"{result}\n"

